-- Safe to run more than once. Requires 20261118000100_tracker_features.sql first.
BEGIN;

-- Section 3 corrections (values match lib/data seed files)
-- Live data (verified 2026-09-03) already has the audit's Rotman texts; only the GMAT/GRE field still disagrees with them.
UPDATE public.programs SET "gmatRequired" = 'Optional', "updatedAt" = now() WHERE id = 'prog-5' AND "gmatRequired" = 'Yes';
-- McMaster/DeGroote checked out accurately: only record the verification date.

-- Provincial awards only fund programs in their province (used to cross-link scholarships and programs).
UPDATE public.scholarships SET provinces = ARRAY['ON'] WHERE id = 'schol-4' AND provinces = '{}';
UPDATE public.scholarships SET provinces = ARRAY['QC'] WHERE id = 'schol-5' AND provinces = '{}';
UPDATE public.scholarships SET provinces = ARRAY['AB'] WHERE id = 'schol-6' AND provinces = '{}';
UPDATE public.scholarships SET provinces = ARRAY['ON'] WHERE id = 'schol-7' AND provinces = '{}';
UPDATE public.scholarships SET provinces = ARRAY['BC'] WHERE id = 'schol-9' AND provinces = '{}';

-- Section 4: faculty named in program notes become supervisor rows, plus the researched supervisor list.
-- Skips anyone already present (matched on first + last name, ignoring "Dr."); a clashing id gets a "-m" suffix.
CREATE OR REPLACE FUNCTION pg_temp.person(n text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT lower(split_part(regexp_replace(trim(n), '^(dr|prof)\.?\s+', '', 'i'), ' ', 1) || ' ' || regexp_replace(trim(n), '^.*\s', ''))
$$;
