INSERT INTO public.supervisors (id, university, name, "researchFocus", email, website, "googleScholar", contacted, responded, "responseType", notes, "createdAt")
SELECT CASE WHEN EXISTS (SELECT 1 FROM public.supervisors x WHERE x.id = src.id) THEN src.id || '-m' ELSE src.id END,
       src.university, src.name, src."researchFocus", src.email, src.website, src."googleScholar", false, false, NULL, src.notes, now()
FROM src
WHERE NOT EXISTS (SELECT 1 FROM public.supervisors x WHERE pg_temp.person(x.name) = pg_temp.person(src.name));

-- Trim faculty names from program notes, only where the note is still the original text.
UPDATE public.programs SET notes = 'Strong fit with GreenBuild Ledger LEED research framing. Supervisors Harish Krishnan and Mahesh Nagarajan are tracked in the Supervisors section.', "updatedAt" = now() WHERE id = 'prog-15' AND notes = 'Target faculty in Supply Chain Analytics / OR / AI. Look at Harish Krishnan (ops mgmt), Mahesh Nagarajan (operations research). Strong fit with GreenBuild Ledger LEED research framing.';
